                        Width: 100,
                        Height: 200,
                    },
                },
            ],
        ];
        testCases.forEach(([input, media, expectedAttributes]) => {
            const xattrs = createFileExtendedAttributes(input, media);
            expect(xattrs).toMatchObject(expectedAttributes);
        });
