                {
                    Common: {
                        ModificationTime: undefined,
                        Size: undefined,
                        BlockSizes: undefined,
                    },
                    Media: {
                        Width: 100,
                        Height: 200,
                    },
                },
            ],
            [
                '{"Common": {"Digests": {}}',
                {
                    Common: {
                        ModificationTime: undefined,
                        Size: undefined,
